steps.script:
if HandoffManager._visible:
	HandoffManager._on_ready_pressed()
return HandoffManager._visible

var main = tree.root.get_node("Main")
var units = GameState.state["units"]
var keep = {"U_CUSTODIAN_GUARD_B": [Vector2(480, 2000), 45.0], "U_BOYZ_K": [Vector2(480, 1240), -45.0]}
for uid in units:
	if keep.has(uid):
		var c = keep[uid][0]
		var step = keep[uid][1]
		var i = 0
		for m in units[uid].get("models", []):
			if not m.get("alive", true):
				continue
			m["position"] = {"x": c.x, "y": c.y + i * step}
			i += 1
		units[uid]["status"] = GameStateData.UnitStatus.DEPLOYED
		units[uid].get("flags", {}).erase("last_shot_idx")
		units[uid].get("flags", {}).erase("shot_recently")
	else:
		for m in units[uid].get("models", []):
			m["alive"] = false
TerrainManager.set_meta("hid_saved_terrain", TerrainManager.terrain_features.duplicate(true))
TerrainManager.terrain_features = []
TerrainManager.emit_signal("terrain_loaded", TerrainManager.terrain_features)
main._recreate_unit_visuals()
main.get_node("ShootingController")._refresh_unit_list(false)
return "ok"

var u = GameState.get_unit("U_BOYZ_K")
var n = 0
for m in u["models"]:
	if not m.get("alive", true):
		continue
	if not TerrainManager.is_model_hidden(m, u):
		return "model %s NOT hidden" % str(m.get("id", "?"))
	n += 1
return n > 0

var why = RulesEngine.explain_target_ineligibility("U_CUSTODIAN_GUARD_B", "U_BOYZ_K", GameState.create_snapshot(false))
print("[hidden_light_terrain_errata_11e] explain: %s" % str(why))
return "%s|%s|%s" % [why.code, str(why.reason.contains("Hidden (in light/dense terrain")), str(int(round(float(why.get("detection_in", -1.0)))))]

var list = tree.root.get_node("Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/ShooterUnitList")
if list.item_count < 1 or not list.get_item_text(0).begins_with("Custodian Guard"):
	return "row 0 is not Custodian Guard"
return "ok"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
for ol in lv.overview_lines:
	if ol["tgt"] == "U_BOYZ_K":
		print("[hidden_light_terrain_errata_11e] overlay line: verdict=%s code=%s label=%s" % [ol["verdict"], ol.get("reason_code", ""), ol.get("label", "")])
		return "%s|%s|%s" % [ol["verdict"], ol.get("reason_code", ""), str(str(ol.get("label", "")).begins_with("Hidden: only visible within 15\""))]
return "no line"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var green = 0
var red = 0
for l in lv.los_lines:
	if l["color"] == Color.GREEN:
		green += 1
	elif l["color"] == Color.RED:
		red += 1
print("[hidden_light_terrain_errata_11e] fan lines: green=%d red=%d" % [green, red])
return "%d|%s" % [green, str(red > 0)]

var g = GameState.state["units"]["U_CUSTODIAN_GUARD_B"]
var i = 0
for m in g["models"]:
	if m.get("alive", true):
		m["position"] = {"x": 480.0, "y": 1700.0 + i * 45.0}
		i += 1
tree.root.get_node("Main")._recreate_unit_visuals()
return "ok"

var g = GameState.state["units"]["U_CUSTODIAN_GUARD_B"]
var i = 0
for m in g["models"]:
	if m.get("alive", true):
		m["position"] = {"x": 480.0, "y": 2000.0 + i * 45.0}
		i += 1
tree.root.get_node("Main")._recreate_unit_visuals()
return "ok"
